jobs=[]
def clip(name,n,loop,desc,subject,ref,kind='human',height=426,cal=True):
 total=n+int(cal);cols=4 if total in (8,7) else 3;rows=(total+cols-1)//cols
 layout=f'EXACT {cols} COLUMNS x {rows} ROWS, row-major equal SQUARE cells. First {n} cells animation. '
 if cal:layout+=f'Cell {n+1} is a neutral upright standing CALIBRATION pose, same anatomical scale as animation. '
 if rows*cols>total:layout+='All remaining cells EMPTY MAGENTA. '
 j=dict(id=name,kind=kind,frames=n,loop=loop,cols=cols,rows=rows,references=[ref],fps=12,prompt=base+subject+layout+desc)
 if kind=='bird':j['targetSpan']=345
 else:j.update(targetHeight=height,calibrationFrame=n if cal else 0)
 jobs.append(j)
